content:
{
  "objective": {
    "factors": [
      "机制覆盖率（识别出的物理机制数量/关键机制全集，需包含摩擦、能量源切断、垂直风切变、流出层阻塞）",
      "量化精度（每个机制对应的典型衰减速率数值区间或公式参数的准确性，单位统一为 kt/hr 或 km/hr）",
      "主导项判别力（是否通过量级对比或敏感性分析明确指出单一主导机制，而非模糊并列）",
      "异质性解释力（不同强度等级气旋衰减速率差异的解释是否基于物理机制的非线性响应，而非仅罗列数据）",
      "不确定性透明度（黑盒表中列出无法确定或争议较大的参数/假设的完整性）"
    ],
    "composition": "Coverage * Accuracy * Discrimination * Heterogeneity / (1 + Uncertainty_Opacity)",
    "rationale": "该函数确保回答不仅全面且准确，还能通过区分主导机制和不同强度的响应特性来体现深层物理理解，同时诚实面对知识边界。"
  },
  "dimensions": [
    {
      "id": "D1",
      "name": "能量收支失衡机制",
      "scope": "涵盖海-气界面潜热输送中断与低层摩擦耗散的量化对比，确定能量输入停止后的净亏损速率。"
    },
    {
      "id": "D2",
      "name": "动力学结构破坏机制",
      "scope": "涵盖环境垂直风切变的倾斜效应与高层流出层（outflow layer）阻塞导致的角动量堆积，评估其对中心气压维持能力的削弱。"
    },
    {
      "id": "D3",
      "name": "强度依赖性非线性响应",
      "scope": "分析初始强度、眼墙结构完整性及边界层高度对不同等级气旋（TS/TD vs Cat 5）衰减速率的差异化影响机制。"
    },
    {
      "id": "D4",
      "name": "时空尺度与观测基准",
      "scope": "界定“迅速减弱”的时间窗口（如登陆后6-24小时）、空间参考系（中心距海岸距离）及不同数据集（Best Track vs 再分析）的口径差异。"
    },
    {
      "id": "D5",
      "name": "认知局限与参数不确定性",
      "scope": "汇总当前气象学中关于摩擦系数、切变临界值及流出效率等关键参数的争议点、测量误差范围及未解的物理过程。"
    }
  ]
}
